namespace Tsumo.Cli
{
    public class StringArrayValue : TemplateValue
    {
        public Tsonic.CSharp.Js.JSArray<string> value;
        public StringArrayValue(Tsonic.CSharp.Js.JSArray<string> value) : base()
        {
            this.value = value;
        }
    }
    public class AnyArrayValue : TemplateValue
    {
        public Tsonic.CSharp.Js.JSArray<TemplateValue> value;
        public AnyArrayValue(Tsonic.CSharp.Js.JSArray<TemplateValue> value) : base()
        {
            this.value = value;
        }
    }
}
